{
  "technical_and_design_decisions": [
    "Use Java 17+ as required by Spring Framework 6.0 for compatibility",
    "Use Maven as the build system for XD project",
    "Use Git for version control and branching",
    "Use Amazon EC2 Windows instance for acceptance test environment",
    "Use Jenkins or GitHub Actions for continuous integration",
    "Leverage Spring Integration (SI) modules for Kafka and Hadoop (SHDP) upgrades",
    "Implement Spark Streaming data processors using Spring Boot and Spark API",
    "Maintain backward compatibility for custom modules during migration"
  ],
  "assumptions": [
    "XD project is based on Spring Framework 6.0 and Java 17",
    "Existing codebase and test suite are available for all features",
    "Developer has full access to repositories, build tools, and cloud resources",
    "Target versions for Kafka SI GA and SHDP GA are known and published",
    "Windows build environment can be set up with standard tools (Maven, JDK, Git) without Cygwin",
    "Acceptance tests are already defined and only need execution on Windows",
    "Pig sample script is a standalone reference, not deeply integrated into XD core",
    "Copyright update is a simple text change in the reference guide source and PDF regeneration"
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Migrate XD from 1.0 to 1.1 and port custom modules",
      "activity_description": "Analyze changes between XD 1.0 and 1.1, update core APIs, migrate custom modules, ensure data pipeline operationalization, and test compatibility.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A2",
      "activity_name": "Provide Pig script/job sample",
      "activity_description": "Create a sample Pig script and job configuration demonstrating integration with XD, write documentation, and verify execution in test environment.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A3",
      "activity_name": "Enable building XD on Windows machine",
      "activity_description": "Adapt build scripts, resolve platform-specific issues (path separators, native dependencies), compile and run unit tests on Windows, document setup instructions.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A4",
      "activity_name": "Set up Windows acceptance test environment and CI",
      "activity_description": "Provision Windows EC2 instance, install required tools, configure test runner, execute existing acceptance tests, and create automated CI pipeline (e.g., Jenkins) for Windows builds.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement Spark Streaming data processors",
      "activity_description": "Design and implement Spark Streaming data processors in XD using Java, Java Lambdas, and Scala; write unit tests and integration tests; document usage.",
      "most_likely_effort": 60
    },
    {
      "activity_id": "A6",
      "activity_name": "Update copyright in reference guide PDF",
      "activity_description": "Locate copyright string in source files (e.g., AsciiDoc or XML), change year from 2014 to 2015, regenerate PDF using existing build tooling, and verify output.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "Upgrade to Kafka SI GA release with backport",
      "activity_description": "Backport existing XD-specific Kafka changes to Spring Integration Kafka module, then upgrade XD dependency to GA release, update configuration, and run integration tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A8",
      "activity_name": "Upgrade to SHDP GA release",
      "activity_description": "Upgrade Spring Hadoop (SHDP) dependency in XD to latest GA release, update any deprecated API usage, run tests to ensure compatibility, and update documentation.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 232
  }
}

